160	export interface ReviewResult {
161	  ok?: true;
162	  error?: string;
163	}
164	
165	/**
166	 * Submit a post-session review + optional tip. Inserts the review (RLS:
167	 * customer owns it), recomputes the provider's rating, and revalidates. Tips
168	 * carry no commission and are aggregated into payouts from the reviews table
169	 * (so they're not double-counted on the session row).
170	 */
171	export async function submitReview(input: ReviewInput): Promise<ReviewResult> {
172	  const profile = await requireRole("customer");
173	  const parsed = reviewSchema.safeParse(input);
174	  if (!parsed.success) return { error: "Please choose a rating." };
175	  const d = parsed.data;
176	
177	  const supabase = await createClient();
178	
179	  // The session must be the caller's own, completed.
180	  const { data: session } = await supabase
181	    .from("sessions")
182	    .select("id, customer_id, provider_id, status")
183	    .eq("id", d.sessionId)
184	    .maybeSingle();
185	  if (!session || session.customer_id !== profile.id) {
186	    return { error: "This session isn't available." };
187	  }
188	
189	  // One review per session.
190	  const { data: existing } = await supabase
191	    .from("reviews")
192	    .select("id")
193	    .eq("session_id", d.sessionId)
194	    .maybeSingle();
195	  if (existing) return { ok: true };
196	
197	  const { error: insErr } = await supabase.from("reviews").insert({
198	    session_id: d.sessionId,
199	    customer_id: profile.id,
200	    provider_id: session.provider_id,
201	    rating: d.rating,
202	    comment: d.comment ?? null,
203	    tip_cents: d.tipCents,
204	  });
205	  if (insErr) return { error: "We couldn't save your review." };
206	
207	  // Recompute the provider's rating (privileged column → service role).
208	  const admin = createAdminClient();
209	  const { data: ratings } = await admin
210	    .from("reviews")
211	    .select("rating")
212	    .eq("provider_id", session.provider_id);
213	  const count = ratings?.length ?? 0;
214	  const sum = (ratings ?? []).reduce((acc, r) => acc + r.rating, 0);
215	  const avg = count > 0 ? roundHalfUp((sum / count) * 100) / 100 : 0;
216	  await admin
217	    .from("providers")
218	    .update({ rating_avg: avg, rating_count: count })
219	    .eq("id", session.provider_id);
220	
221	  revalidatePath(`/session/${session.id}/summary`);
222	  revalidatePath("/provider/dashboard");
223	  return { ok: true };
224	}
